const img=p=>p.img||IMG[p.code]||IMG.classic,pimg=s=>s&&s[0]=='@'?IMG[s.slice(1)]:s;
const shrink=(f,max=900,q=.82)=>new Promise(r=>{if(!f.type.startsWith('image/'))return r(null);const i=new Image();i.onload=()=>{const k=Math.min(1,max/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=i.width*k;c.height=i.height*k;c.getContext('2d').drawImage(i,0,0,c.width,c.height);r(c.toDataURL(/png|webp/.test(f.type)?'image/webp':'image/jpeg',q))};i.onerror=()=>r(null);i.src=URL.createObjectURL(f)});
function modal(h){const o=document.createElement('div');o.className='ov';o.innerHTML=`<div class="md">${h}</div>`;o.onclick=e=>{if(e.target===o)o.remove()};document.body.append(o);return o}
